select json_build_object('weeks_with_meat',(select count(distinct week_id) from raw_week_items where section='meat'),'meat_items',(select count(*) from raw_week_items where section='meat'),'meat_lib',(select count(*) from raw_items where section='meat'),'t',(select json_agg(x) from (select w.label,count(*) n from raw_week_items i join raw_weeks w on w.id=i.week_id where i.section='meat' group by 1 order by min(w.week_date) desc limit 6) x)) r;
